	/** 
	 * updating a BankAccount.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a BankAccount." );

		StringBuilder msg = new StringBuilder( "Failed to update a BankAccount : " );        
		BankAccount entity = read();
		UpdateBankAccountCommand command = generateUpdateCommand();
		command.setBankAccountId(entity.getBankAccountId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created BankAccount." );

			// for use later on...
			bankAccountId = entity.getBankAccountId();

			BankAccountService proxy = BankAccountService.getBankAccountInstance();  

			proxy.updateBankAccount( command ).get();

			LOGGER.info( "-- Successfully saved BankAccount - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + bankAccountId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a BankAccount.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created BankAccount." );

		BankAccount entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read BankAccount with id " + bankAccountId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read BankAccount with id " + bankAccountId );

			throw e;
		}

		try{
			BankAccountService.getBankAccountInstance().delete( new DeleteBankAccountCommand( entity.getBankAccountId() ) ).get();
			LOGGER.info( "-- Successfully deleted BankAccount with id " + bankAccountId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete BankAccount with id " + bankAccountId );

			throw e;
		}
	}

